<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { axiosInstance } from '@halo-dev/api-client'
type Config = { enabled: boolean; autoSync: boolean; autoPublish: boolean; appId: string; author: string; defaultCoverUrl: string; defaultThumbMediaId: string; hasSecret: boolean }
type Job = { id: string; title: string; state: string; error: string; mediaId: string; publishId: string; articleUrl: string; touched: string; appId: string }
const base = '/apis/console.api.space.onoe.cn/v1alpha1/officialaccount'
const config = ref<Config>({enabled:false,autoSync:false,autoPublish:false,appId:'',author:'',defaultCoverUrl:'',defaultThumbMediaId:'',hasSecret:false})
const secret = ref(''), acknowledged = ref(false), saved = ref(''), busy = ref(false), loading = ref(true), error = ref(''), message = ref(''), selected = ref('')
const jobs = ref<Job[]>([]), articles = ref<{id:string;title:string}[]>([])
const dirty = computed(() => secret.value.length > 0 || JSON.stringify(config.value) !== saved.value)
const labels:Record<string,string> = {QUEUED:'等待同步',PREPARING:'处理图片与排版',DRAFT_SUBMITTING:'正在创建草稿',DRAFT_READY:'已同步草稿箱',PUBLISH_SUBMITTING:'正在提交发表',PUBLISHING:'微信处理中',PUBLISHED:'已发表',FAILED:'同步失败',PAUSED:'已暂停',SUPERSEDED:'文章已有新版本',UNCERTAIN:'结果待核对',PUBLISH_UNKNOWN:'发表结果待查询',PUBLISH_FAILED:'微信未发表成功'}
function detail(e:unknown){const value=e as {response?:{data?:{detail?:string}}};return value.response?.data?.detail || '请求失败，请检查网络或管理权限后重试。'}
async function loadJobs(){const {data}=await axiosInstance.get(base+'/jobs');jobs.value=data}
async function load(){loading.value=true;error.value='';try{const [c,p]=await Promise.all([axiosInstance.get(base+'/config'),axiosInstance.get(base+'/articles')]);config.value=c.data;acknowledged.value=c.data.autoPublish;secret.value='';saved.value=JSON.stringify(config.value);articles.value=p.data;await loadJobs()}catch(e){error.value=detail(e)}finally{loading.value=false}}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await action()}catch(e){error.value=detail(e)}finally{busy.value=false}}
async function refresh(){await run(loadJobs)}
function validateFields(){const id=config.value.appId.trim();if(config.value.enabled&&!id)return '请填写公众号AppID';if(id&&!/^wx[a-zA-Z0-9]{16}$/.test(id))return '公众号AppID格式不正确：应为wx开头共18位，当前'+id.length+'位，请从公众号后台完整复制';if([...config.value.author.trim()].length>8)return '署名超过8字，请缩短署名';if(secret.value.trim().length>256)return '公众号AppSecret长度异常，请重新复制';return ''}
async function save(){await run(async()=>{const problem=validateFields();if(problem){error.value=problem;return}const automatic=config.value.enabled&&config.value.autoSync;const publishing=automatic&&config.value.autoPublish;if(publishing&&!acknowledged.value){error.value='请先确认自动发表会将文章公开至公众号。';return}const {data}=await axiosInstance.put(base+'/config',{...config.value,autoSync:automatic,autoPublish:publishing,appSecret:secret.value,confirmAutoPublish:acknowledged.value});config.value=data;secret.value='';saved.value=JSON.stringify(data);message.value='公众号配置已保存。'})}
function requireSaved(){if(dirty.value){error.value='配置已修改，请先保存后再操作。';return false}return true}
async function test(){if(!requireSaved())return;await run(async()=>{const {data}=await axiosInstance.post(base+'/test');message.value=data.message})}
async function sync(){if(!requireSaved()||!selected.value)return;await run(async()=>{await axiosInstance.post(base+'/sync',{postName:selected.value});message.value='已加入同步队列，可在下方查看进度。';await loadJobs()})}
async function retry(job:Job){if(!requireSaved())return;const uncertain=job.state==='UNCERTAIN';if(uncertain&&!window.confirm('上次微信请求的结果未确认。请先到公众号后台核对：确认没有生成重复草稿或发表记录后，再继续重试。确定已完成核对？'))return;await run(async()=>{await axiosInstance.post(base+'/jobs/'+encodeURIComponent(job.id)+'/retry',{confirmNoDuplicate:uncertain});await loadJobs()})}
async function publish(job:Job){if(!requireSaved()||!window.confirm('确认将这篇已同步的草稿公开发表到公众号？发表接口不等于向粉丝群发通知。'))return;await run(async()=>{await axiosInstance.post(base+'/jobs/'+encodeURIComponent(job.id)+'/publish',{confirmPublic:true});message.value='已提交发表任务，最终结果以微信返回的状态为准。';await loadJobs()})}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await load();timer=setInterval(()=>{if(!loading.value&&!busy.value)loadJobs().catch(()=>{})},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
 <div class="oa-panel">
 <section class="xr-card oa-intro"><div class="oa-kicker">WECHAT · 公众号同步</div><h2>文章写一次，博客与公众号相连。</h2><p class="xr-muted">发布公开博客文章后，自动处理正文图片与基础排版，同步至公众号草稿箱。可选择自动发表，或在草稿完成后单独确认发表。</p><p class="oa-note">公众号与小程序的 AppID、AppSecret 不通用。草稿、素材与发表能力以公众号后台实际接口权限为准；发表不等于向粉丝群发通知。</p></section>
 <div v-if="error" class="xr-alert xr-error" role="alert">{{error}}</div><div v-if="message" class="xr-alert xr-success" role="status">{{message}}</div>
 <section class="xr-card"><div class="xr-section-head"><h3>公众号连接</h3><span class="xr-tag">{{config.enabled?'已启用':'默认关闭'}}</span></div>
  <form @submit.prevent="save" class="oa-form"><label class="oa-toggle"><input v-model="config.enabled" type="checkbox" :disabled="busy || loading"/>启用公众号同步</label>
   <div class="oa-grid"><label>公众号 AppID<input v-model.trim="config.appId" autocomplete="off" placeholder="wx开头，共18位，请完整复制" maxlength="128" :disabled="busy || loading"/></label><label>公众号 AppSecret<input v-model="secret" type="password" autocomplete="new-password" :placeholder="config.hasSecret?'已保存，留空不修改':'仅保存至当前 Halo 服务端'" maxlength="256" :disabled="busy || loading"/></label><label>署名（选填，最多8字）<input v-model="config.author" maxlength="8" :disabled="busy || loading"/></label><label>默认封面图片地址（选填）<input v-model.trim="config.defaultCoverUrl" placeholder="https://…" :disabled="busy || loading"/></label></div>
   <details><summary>已有公众号永久封面素材</summary><label>默认封面 media_id<input v-model.trim="config.defaultThumbMediaId" placeholder="无文章封面时使用，须属于当前公众号" maxlength="256" :disabled="busy || loading"/></label></details>
   <p class="xr-muted">优先使用文章封面，其次正文首图，再使用默认封面或永久素材。图片会复制到当前公众号。请先将 Halo 服务器公网出口 IP 加入微信白名单。</p>
   <label class="oa-toggle"><input v-model="config.autoSync" type="checkbox" :disabled="busy || loading || !config.enabled"/>公开文章发布后自动同步（后续发布新版本也同步）</label>
   <label class="oa-toggle"><input v-model="config.autoPublish" type="checkbox" :disabled="busy || loading || !config.enabled || !config.autoSync"/>同步后自动公开发表</label>
   <label v-if="config.autoPublish" class="oa-warning"><input v-model="acknowledged" type="checkbox" :disabled="busy || loading"/>我确认：后续公开文章将自动提交公众号发表；公众号需具备相应权限，微信仍可能审核失败。</label>
   <div class="xr-actions"><button class="xr-button" :disabled="busy || loading" type="submit">{{busy?'处理中…':'保存配置'}}</button><button class="xr-button xr-secondary" type="button" :disabled="busy || loading || !config.enabled" @click="test">验证连接</button></div>
  </form>
 </section>
 <section class="xr-card"><div class="xr-section-head"><div><h3>同步已有文章</h3><p class="xr-muted">只读取已发布的公开版本；重复操作同一版本不会新建重复任务。</p></div></div><div class="oa-manual"><select v-model="selected" :disabled="busy || loading"><option value="">选择一篇公开文章（最新100篇）</option><option v-for="post in articles" :key="post.id" :value="post.id">{{post.title}}</option></select><button class="xr-button" :disabled="busy || loading || !selected || !config.enabled" @click="sync">同步文章</button></div></section>
 <section class="xr-card"><div class="xr-section-head"><h3>同步记录</h3><button class="xr-button xr-secondary" :disabled="busy || loading" @click="refresh">刷新</button></div><p v-if="!jobs.length" class="xr-muted">还没有同步记录，保存配置后可选择文章试一次。</p><article v-for="job in jobs" :key="job.id" class="oa-job"><div class="oa-job-head"><strong>{{job.title}}</strong><span class="xr-tag">{{labels[job.state]||job.state}}</span></div><p v-if="job.error" class="oa-job-error">{{job.error}}</p><p class="xr-muted oa-meta">公众号 {{job.appId}} · {{job.touched}}</p><div class="xr-actions"><button v-if="job.state==='DRAFT_READY'" class="xr-button xr-secondary" :disabled="busy || !config.enabled" @click="publish(job)">确认发表</button><button v-if="job.publishId && job.state!=='PUBLISHED' || ['FAILED','PAUSED','UNCERTAIN'].includes(job.state)" class="xr-button xr-secondary" :disabled="busy || !config.enabled" @click="retry(job)">{{job.publishId?'查询发表结果':job.state==='UNCERTAIN'?'核对后重试':'重试'}}</button><a v-if="job.articleUrl" class="xr-button xr-secondary" :href="job.articleUrl" target="_blank" rel="noopener noreferrer">查看公众号文章</a></div></article></section>
 </div>
</template>
<style scoped>
.oa-panel{font-size:14px;line-height:1.65;color:var(--ui-text)}.oa-panel *{box-sizing:border-box}.xr-card{background:var(--ui-surface);padding:28px;margin-bottom:22px;border-radius:24px;box-shadow:0 4px 22px rgba(0,0,0,.025)}h2,h3,p{margin:0}h2{font-size:24px;line-height:1.5;font-weight:600}h3{font-size:18px;line-height:1.5;font-weight:600}.xr-muted{color:var(--ui-secondary)}.xr-section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.xr-tag{background:var(--ui-tint);color:var(--ui-accent-text);font-size:12px;padding:4px 12px;border-radius:20px;white-space:nowrap}.xr-actions{display:flex;gap:12px;flex-wrap:wrap}.xr-button{display:inline-flex;justify-content:center;align-items:center;min-height:42px;border:0;border-radius:24px;padding:10px 22px;font:inherit;font-weight:500;line-height:1.5;cursor:pointer;color:var(--ui-on-accent);background:var(--ui-accent);text-decoration:none;white-space:nowrap}.xr-button:disabled{opacity:.45;cursor:not-allowed}.xr-secondary{background:var(--ui-soft);color:var(--ui-secondary)}label{display:block;font-weight:500}.oa-form input:not([type=checkbox]){display:block;width:100%;padding:12px 15px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-soft);color:var(--ui-text);font:inherit;outline:none}.oa-form input:focus{border-color:var(--ui-accent-soft);box-shadow:0 0 0 3px var(--ui-tint)}.oa-form input[type=checkbox]{width:17px;height:17px}.xr-alert{padding:14px 18px;border-radius:14px;background:var(--ui-tint);margin-bottom:18px;color:var(--ui-accent-text)}.oa-job:last-child{padding-bottom:0}@media(max-width:820px){.xr-card{padding:22px}.xr-section-head{gap:12px}.oa-manual .xr-button{width:100%}}
.oa-intro h2{margin:10px 0 12px}.oa-kicker{font-size:12px;letter-spacing:1px;color:var(--ui-accent-text)}.oa-note{padding:14px 18px;background:var(--ui-tint);border-radius:14px;color:var(--ui-secondary);margin-top:18px!important}.oa-form{display:grid;gap:18px}.oa-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.oa-form label{margin:0}.oa-form input:not([type=checkbox]){margin-top:8px}.oa-form .oa-toggle,.oa-warning{display:flex;gap:10px;align-items:flex-start;font-weight:400}.oa-toggle input,.oa-warning input{accent-color:var(--ui-accent);margin-top:5px;flex-shrink:0}.oa-warning{padding:15px;border-radius:12px;background:var(--ui-tint);color:var(--ui-accent-text)}.oa-form summary{cursor:pointer;color:var(--ui-secondary);margin-bottom:12px}.oa-manual{display:flex;gap:16px}.oa-manual select{flex:1;min-width:0;background:var(--ui-soft);border:1px solid var(--ui-border);padding:12px 16px;border-radius:12px;color:var(--ui-text);font:inherit}.oa-job{padding:20px 0;border-top:1px solid var(--ui-border)}.oa-job-head{display:flex;gap:16px;justify-content:space-between;align-items:flex-start}.oa-job-error{color:var(--ui-accent-text);margin:10px 0!important}.oa-meta{font-size:12px;overflow-wrap:anywhere;margin:10px 0!important}.oa-job .xr-tag{flex-shrink:0}@media(max-width:820px){.oa-grid{grid-template-columns:1fr}.oa-manual{flex-direction:column}.oa-job-head{flex-direction:column}}
</style>
